package org.brightstats.desktop;

import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.stats.*;

/** Population assumptions are deliberately editable separately from optimizer starts. */
final class SimulationDialog {
    private SimulationDialog(){}
    static SemSimulation.Design example(){
        var model=new SemModel.Model(List.of("Outcome"),new int[]{0},new double[1][1],new double[][]{{1}},new double[1],List.of(new SemModel.Parameter("Mean",List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,0,0)),.35,1)));
        return new SemSimulation.Design(model,null,new int[]{30,80,150},200,List.of(new SemSimulation.Target("Mean",0)),SemSimulation.Distribution.NORMAL,7,SemSimulation.Missingness.NONE,0,0,1,SemSimulation.Uncertainty.MODEL,.05,.8,42,1,false,FimlSem.Options.defaults());
    }
    static Optional<SemSimulation.Design> show(Window owner,SemSimulation.Design current){
        Dialog<SemSimulation.Design> dialog=new Dialog<>();dialog.initOwner(owner);dialog.setTitle("Power and precision studio");dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);
        Label note=new Label("Choose a hypothesized population and independent fitting starts. These assumptions are not estimated from your working dataset. Every attempt is counted, including failed or nonregular fits. Recommendations cover tested sample sizes only.");note.setWrapText(true);note.setMaxWidth(800);
        GridPane parameters=new GridPane();parameters.setHgap(10);parameters.setVgap(7);String[] headings={"Parameter","Population value","Analysis start","Study target","Null value"};for(int j=0;j<headings.length;j++)parameters.add(new Label(headings[j]),j,0);
        Map<String,SemModel.Parameter> starts=new HashMap<>();current.analysis().parameters().forEach(p->starts.put(p.name(),p));Map<String,Double> targets=new HashMap<>();current.targets().forEach(t->targets.put(t.parameter(),t.nullValue()));
        List<TextField> populationFields=new ArrayList<>(),startFields=new ArrayList<>(),nullFields=new ArrayList<>();List<CheckBox> targetFields=new ArrayList<>();
        int row=1;for(var parameter:current.population().parameters()){
            TextField population=field(Double.toString(parameter.start()),"Population value: "+parameter.name()),start=field(Double.toString(starts.get(parameter.name()).start()),"Analysis start: "+parameter.name()),nullValue=field(Double.toString(targets.getOrDefault(parameter.name(),0.0)),"Null value: "+parameter.name());CheckBox selected=new CheckBox();selected.setSelected(targets.containsKey(parameter.name()));selected.setAccessibleText("Study target: "+parameter.name());
            parameters.addRow(row++,new Label(parameter.name()),population,start,selected,nullValue);populationFields.add(population);startFields.add(start);nullFields.add(nullValue);targetFields.add(selected);
        }
        TextField sizes=field(Arrays.toString(current.sampleSizes()).replaceAll("[\\[\\]]",""),"Sample sizes"),repetitions=field(Integer.toString(current.repetitions()),"Repetitions per sample size"),seed=field(Long.toString(current.seed()),"Seed"),workers=field(Integer.toString(current.workers()),"Workers"),degrees=field(Double.toString(current.studentDegreesOfFreedom()),"Student t degrees of freedom"),missing=field(Double.toString(current.missingRate()),"Missing fraction"),slope=field(Double.toString(current.marSlope()),"MAR driver slope"),alpha=field(Double.toString(current.alpha()),"Per-target alpha"),power=field(Double.toString(current.desiredPower()),"Desired power"),confidence=field(Double.toString(current.estimator().confidence()),"Interval confidence");sizes.setId("simulation-sizes");
        ComboBox<SemSimulation.Distribution> distribution=new ComboBox<>();distribution.getItems().setAll(SemSimulation.Distribution.values());distribution.setValue(current.distribution());ComboBox<SemSimulation.Missingness> missingness=new ComboBox<>();missingness.getItems().setAll(SemSimulation.Missingness.values());missingness.setValue(current.missingness());ComboBox<SemSimulation.Uncertainty> uncertainty=new ComboBox<>();uncertainty.getItems().setAll(SemSimulation.Uncertainty.values());uncertainty.setValue(current.uncertainty());ComboBox<String> driver=new ComboBox<>();for(int index:current.population().observed())driver.getItems().add(current.population().variables().get(index));driver.getSelectionModel().select(current.marDriver());
        GridPane settings=new GridPane();settings.setHgap(12);settings.setVgap(8);Control[] controls={sizes,repetitions,seed,workers,distribution,degrees,missingness,missing,driver,slope,uncertainty,alpha,power,confidence};String[] labels={"Sample sizes (comma separated)","Repetitions per sample size","Seed","Workers (1–4)","Disturbance distribution","Student t degrees of freedom (>4)","Missingness scenario","Missing fraction (0–0.8)","Observed MAR driver","MAR slope","Uncertainty estimator","Per-target alpha","Desired power","Interval confidence"};for(int i=0;i<controls.length;i++){settings.add(new Label(labels[i]),0,i);settings.add(controls[i],1,i);controls[i].setAccessibleText(labels[i]);}
        CheckBox retain=new CheckBox("Retain individual replicate results (bounded to 20,000 target records)");retain.setSelected(current.retainReplicates());Label error=new Label();error.setId("simulation-error");error.setWrapText(true);VBox body=new VBox(14,note,new Label("Population and fitting assumptions"),parameters,new Separator(),settings,retain,error);body.setPadding(new Insets(16));ScrollPane scroll=new ScrollPane(body);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(620);scroll.setPrefViewportWidth(850);dialog.getDialogPane().setContent(scroll);SemSimulation.Design[] result={null};
        dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{
            List<SemModel.Parameter> populationParameters=new ArrayList<>(),analysisParameters=new ArrayList<>();List<SemSimulation.Target> selected=new ArrayList<>();for(int i=0;i<populationFields.size();i++){var parameter=current.population().parameters().get(i);populationParameters.add(value(parameter,number(populationFields.get(i))));analysisParameters.add(value(starts.get(parameter.name()),number(startFields.get(i))));if(targetFields.get(i).isSelected())selected.add(new SemSimulation.Target(parameter.name(),number(nullFields.get(i))));}
            var p=current.population();var a=current.analysis();var population=new SemModel.Model(p.variables(),p.observed(),p.directed(),p.covariance(),p.intercepts(),populationParameters);var analysis=new SemModel.Model(a.variables(),a.observed(),a.directed(),a.covariance(),a.intercepts(),analysisParameters);int[] ns=Arrays.stream(sizes.getText().split(",",-1)).map(String::strip).mapToInt(Integer::parseInt).toArray();var e=current.estimator();result[0]=new SemSimulation.Design(population,analysis,ns,Integer.parseInt(repetitions.getText().strip()),selected,distribution.getValue(),number(degrees),missingness.getValue(),number(missing),driver.getSelectionModel().getSelectedIndex(),number(slope),uncertainty.getValue(),number(alpha),number(power),Long.parseLong(seed.getText().strip()),Integer.parseInt(workers.getText().strip()),retain.isSelected(),new FimlSem.Options(e.maxIterations(),e.gradientTolerance(),e.functionTolerance(),number(confidence)));SemSimulation.validate(result[0]);
        }catch(RuntimeException invalid){error.setText(invalid.getMessage()==null?"Check the study settings.":invalid.getMessage());event.consume();}});
        dialog.setResultConverter(button->button==ButtonType.OK?result[0]:null);return dialog.showAndWait();
    }
    static SemSimulation.Design smoke(Window owner,SemSimulation.Design current,java.nio.file.Path image)throws Exception{
        Throwable[] failure={null};javafx.application.Platform.runLater(()->{javafx.stage.Window window=null;try{window=javafx.stage.Window.getWindows().stream().filter(w->w instanceof javafx.stage.Stage stage&&stage.getTitle().equals("Power and precision studio")).findFirst().orElseThrow();var root=window.getScene().getRoot();var pane=(DialogPane)root.lookup(".dialog-pane");var sizes=(TextField)root.lookup("#simulation-sizes");sizes.setText("10");((Button)pane.lookupButton(ButtonType.OK)).fire();if(!window.isShowing())throw new AssertionError("Invalid simulation settings accepted");sizes.setText(Arrays.toString(current.sampleSizes()).replaceAll("[\\[\\]]",""));((Label)root.lookup("#simulation-error")).setText("");pane.applyCss();pane.layout();java.nio.file.Files.deleteIfExists(image);GraphicExport.png(image,pane,1);((Button)pane.lookupButton(ButtonType.OK)).fire();}catch(Throwable error){failure[0]=error;if(window!=null)window.hide();}});var result=show(owner,current);if(failure[0]!=null)throw new AssertionError("Simulation dialog smoke failed",failure[0]);return result.orElseThrow(()->new AssertionError("Valid simulation design not returned"));
    }
    private static TextField field(String value,String label){TextField field=new TextField(value);field.setAccessibleText(label);field.setPrefColumnCount(12);return field;}
    private static double number(TextField field){double value=Double.parseDouble(field.getText().strip());if(!Double.isFinite(value))throw new IllegalArgumentException("Enter a finite number for "+field.getAccessibleText()+".");return value;}
    private static SemModel.Parameter value(SemModel.Parameter p,double value){return new SemModel.Parameter(p.name(),p.locations(),value,p.scale(),p.lower(),p.upper());}
}
